<?php
/* TEMPORARY (owner, 12 Nov 2026): full backup, then save the researched Art Map museums and art galleries
   (21 places) as DRAFTS in site_settings 'art_places', only if that key does not exist yet. Nothing else
   changes. Locked by a secret key, runs once. Removed straight after. */
if (!hash_equals('e7bcfa9e0bb6e64a80af15de2a5cd88839d719b7d36c60a9132d4d805e0f5bab', hash('sha256', (string) ($_GET['k'] ?? '')))) { http_response_code(404); exit; }
require_once __DIR__ . '/config.php';
header('Content-Type: text/plain; charset=utf-8'); header('Cache-Control: no-store'); header('X-Robots-Tag: noindex');
@set_time_limit(300);
$db = getDB();
$dbName = (string) $db->query('SELECT DATABASE()')->fetchColumn();
$show = function () use ($db) {
    $v = $db->query("SELECT setting_value FROM site_settings WHERE setting_key = 'art_places'")->fetchColumn();
    if ($v === false) { echo "art_places: not set\n"; return; }
    $j = json_decode((string) $v, true) ?: []; echo 'art_places: ' . count($j) . " places\n";
    foreach ($j as $p) echo $p['kind'], ' | ', $p['city'], ' | ', $p['name_en'], ' | ', $p['status'], "\n";
};
if (($_GET['a'] ?? '') !== 'run') { echo "ready, database $dbName\n"; $show(); exit; }
if (is_file(__DIR__ . '/.logs/zz-artmap-done')) { echo "already run\n"; $show(); exit; }
if ($db->query("SELECT COUNT(*) FROM site_settings WHERE setting_key = 'art_places'")->fetchColumn()) { echo "art_places already exists, nothing changed\n"; $show(); exit; }

/* 1. full backup */
$dir = __DIR__ . '/.backups';
if (!is_dir($dir)) { @mkdir($dir, 0700, true); }
if (!is_file($dir . '/.htaccess')) { @file_put_contents($dir . '/.htaccess', "Require all denied\n"); }
$file = $dir . '/db-' . preg_replace('/[^a-z0-9_]/i', '', $dbName) . '-' . gmdate('Ymd-His') . '.sql.gz';
$gz = gzopen($file, 'wb6');
if (!$gz) { echo "backup FAILED: cannot write\n"; exit; }
gzwrite($gz, "-- Oweili full backup " . gmdate('c') . "\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n");
$tables = $db->query('SHOW FULL TABLES WHERE Table_type = "BASE TABLE"')->fetchAll(PDO::FETCH_COLUMN);
$rows = 0;
foreach ($tables as $t) {
    $t = str_replace('`', '', (string) $t);
    $c = $db->query("SHOW CREATE TABLE `$t`")->fetch(PDO::FETCH_NUM);
    gzwrite($gz, "\nDROP TABLE IF EXISTS `$t`;\n" . $c[1] . ";\n");
    $st = $db->query("SELECT * FROM `$t`");
    while ($r = $st->fetch(PDO::FETCH_NUM)) {
        $vals = array_map(fn($v) => $v === null ? 'NULL' : $db->quote((string) $v), $r);
        gzwrite($gz, "INSERT INTO `$t` VALUES (" . implode(',', $vals) . ");\n");
        $rows++;
    }
}
gzwrite($gz, "\nSET FOREIGN_KEY_CHECKS=1;\n");
gzclose($gz);
$size = (int) filesize($file);
if ($size < 500) { echo "backup FAILED (too small)\n"; exit; }
echo "backup ok: .backups/" . basename($file) . " (" . count($tables) . " tables, $rows rows, $size bytes)\n";

/* 2. the drafts */
$json = base64_decode('');
$j = json_decode($json, true);
if (!is_array($j) || count($j) !== 21) { echo "data FAILED\n"; exit; }
foreach ($j as $p) if (($p['status'] ?? '') !== 'draft') { echo "not a draft, stopped\n"; exit; }
$db->prepare("INSERT INTO site_settings (setting_key, setting_value) VALUES ('art_places', :v)")->execute([':v' => $json]);
@file_put_contents(__DIR__ . '/.logs/zz-artmap-done', gmdate('c'));
echo "saved\n"; $show();
